"""Replacements responding to independent blind/options-visible review.

Initial rejected drafts are retained separately; no failed label is silently
counted. These functions replace the corresponding mutable candidate recipes.
"""
import itertools,math
import sympy as s
from common import tex as L,prose as T,eq,truth
R=s.Rational
x=s.symbols('x',positive=True)
def install(core):
 register=core['register'];numeric=core['numeric'];categorical=core['categorical']

 @register('Dirichlet-moment-uniqueness','Dirichlet-series-coefficient-recovery','smallest-index-dominance','Decides whether specified exponential moment data can be supported on the reciprocal-integer lattice; no consistent coefficient sequence is supplied in the question.',('dominated convergence','absolutely convergent series'))
 def moment(fid,i):
  pairs=[(R(3),R(9,2)),(R(5),R(11,2)),(R(13,2),R(7)),(R(15,2),R(17,2)),(R(9),R(21,2)),(R(11),R(23,2)),(R(25,2),R(13)),(R(27,2),R(29,2))];a,b=pairs[i]
  first='exists' if a.q==1 else 'does not exist';second='exists' if b.q==1 else 'does not exist';code=first+'|'+second
  opts=[(u+'|'+v,r'\left('+T(u)+r',\ '+T(v)+r'\right)','correct' if u+'|'+v==code else 'Treat arbitrary positive exponential moment rates as representable on a discrete reciprocal-integer support') for u,v in itertools.product(['exists','does not exist'],repeat=2)]
  Q=T('For each displayed b separately, decide whether there exists an absolutely summable real sequence satisfying every displayed moment identity. Choose the ordered pair of existence conclusions.')+r'\quad\sum_{n=1}^{\infty}|a_n|<\infty,\qquad\sum_{n=1}^{\infty}\frac{a_n}{n^k}=b^{-k}\quad(k=1,2,\ldots),\qquad b='+L(a)+r',\quad b='+L(b)+r'.'
  steps=[T('If b is a positive integer, a sequence supported only at that integer with coefficient one gives a solution.'),T('Conversely, any solution is nonzero. Let j be its smallest nonzero coefficient index, multiply the moment identity by j to the power k, and control the remaining tail by absolute summability.'),r'a_j+\sum_{n>j}a_n(j/n)^k=(j/b)^k,\qquad\sum_{n>j}a_n(j/n)^k\longrightarrow0.',T('The left side has a finite nonzero limit. The right side tends to zero if j is smaller than b and diverges if j is greater than b. Thus j must equal b, forcing b to be an integer.'),r'\textnormal{A solution exists}\iff b\in\{1,2,3,\ldots\}.',r'b='+L(a)+T(': '+first+'.')+r'\qquad b='+L(b)+T(': '+second+'.')]
  checks=[truth('first lattice membership determined exactly',(a.q==1)==(first=='exists')),truth('second lattice membership determined exactly',(b.q==1)==(second=='exists')),eq('strictly smaller reciprocal ratio contracts',s.limit((R(3,4))**x,x,s.oo),0)]
  return categorical(fid,i,Q,code,opts,steps,checks,['Dominated convergence on counting measure uses the l1 envelope |a_n|. Well-ordering gives a smallest nonzero index. The target is never zero, ruling out the zero sequence. Positive integer b admits the explicit delta witness; noninteger b is impossible, even allowing signed coefficients.'],{'bases':[str(a),str(b)],'qualityRoute':'support-existence-v2'})

 @register('Carleman-geometric-mean-constant','sharp-Carleman-geometric-mean-series','weighted-AMGM-telescope-and-logarithmic-sharpness','Different polynomial weights change every weighted geometric mean; a telescoping AM-GM construction and a logarithmic asymptotic prove its optimal constant.',('weighted AM-GM','nonnegative summation','Riemann sums with integrable logarithmic endpoint'))
 def carleman(fid,i):
  m=s.Integer(i+2);A=s.exp(1/m)
  W=[(s.exp(1/(m+1)),'shift the polynomial-weight degree upward'),(s.exp(1/(m-1)),'shift the polynomial-weight degree downward'),(s.exp(2/m),'double the logarithmic moment correction'),(s.exp(1/(2*m)),'halve the logarithmic moment correction'),(s.exp(m),'invert the degree-dependent exponent'),(s.exp((m-1)/m),'use the complement of the logarithmic moment')]
  Q=T('Find the least constant C for which this inequality holds for every nonnegative real sequence with finite sum. The weights and their partial sums are defined below.')+r'\quad\lambda_k=\binom{k+'+L(m-2)+r'}{'+L(m-1)+r'},\quad\Lambda_n=\sum_{k=1}^{n}\lambda_k=\binom{n+'+L(m-1)+r'}{'+L(m)+r'},\quad\sum_{n=1}^{\infty}\prod_{k=1}^{n}a_k^{\lambda_k/\Lambda_n}\le C\sum_{k=1}^{\infty}a_k.'
  steps=[T('Use positive auxiliary weights whose weighted products telescope. All exponents below use the same displayed weights.'),r'c_k=\frac{(k+'+L(m)+r')^{\Lambda_k/\lambda_k}}{(k+'+L(m-1)+r')^{\Lambda_{k-1}/\lambda_k}},\quad\Lambda_0=0,\qquad\prod_{k=1}^{n}c_k^{\lambda_k}=(n+'+L(m)+r')^{\Lambda_n}.',T('Weighted AM-GM applied to the products of c and a gives a summable upper bound.'),r'\prod_{k=1}^{n}a_k^{\lambda_k/\Lambda_n}\le\frac{\sum_{k=1}^{n}\lambda_kc_ka_k}{(n+'+L(m)+r')\Lambda_n},\qquad\sum_{n=k}^{\infty}\frac1{(n+'+L(m)+r')\Lambda_n}=\frac1{'+L(m)+r'\Lambda_k}.',T('Reverse the nonnegative sums and simplify each resulting coefficient.'),r'\frac{\lambda_kc_k}{'+L(m)+r'\Lambda_k}=\left(1+\frac1{k+'+L(m-1)+r'}\right)^{(k+'+L(m-1)+r')/'+L(m)+r'}<e^{1/'+L(m)+r'}.',T('For sharpness, take the reciprocal sequence through N and zero afterward. Polynomial-weight Riemann sums, with a controlled logarithmic endpoint, determine each weighted geometric mean.'),r'\frac{\sum_{k=1}^{n}\lambda_k\ln k}{\Lambda_n}=\ln n-\frac1{'+L(m)+r'}+o(1),\qquad\prod_{k=1}^{n}(1/k)^{\lambda_k/\Lambda_n}\sim\frac{e^{1/'+L(m)+r'}}n.',T('Consequently the ratio of the two finite sums tends to this exponential constant as N increases. Every truncated sequence is admissible, proving sharpness.'),r'C=e^{1/'+L(m)+r'}.']
  n=s.symbols('n',integer=True,positive=True);La=s.binomial(n+m-1,m);Lb=s.binomial(n+m,m)
  checks=[eq('weight-tail telescope',s.expand_func(1/La-1/Lb),s.expand_func(m/((n+m)*La))),eq('normalized logarithmic weight moment',s.integrate(m*x**(m-1)*s.log(x),(x,0,1)),-1/m)]
  return numeric(fid,i,Q,A,W,steps,checks,['The binomial hockey-stick identity gives Lambda. Weighted AM-GM is valid for nonnegative entries and positive weights. The displayed reciprocal-Lambda difference telescopes to the stated tail because Lambda tends to infinity. Lambda_n~n^m/m! and lambda_k~k^(m-1)/(m-1)! reduce the log correction to m integral_0^1 t^(m-1)ln t=-1/m; the endpoint contribution is uniformly controlled by an integrable logarithmic power, and lower polynomial terms are negligible. Zeros after N make all later weighted geometric means zero.'],{'weightDegreePlusOne':int(m),'qualityRoute':'polynomial-weight-v2'})

 @register('Dyson-alternating-cube','Dyson-constant-term-recurrence','Laurent-constant-term-and-multinomial-asymptotics','An asymptotic alternating binomial sum cannot be resolved by a small direct sum; constant-term induction and three-factor Stirling normalization are both necessary.',('Laurent polynomials','multinomial recurrence','Stirling asymptotics'))
 def dyson(fid,i):
  m=s.Integer(i+3);B=(m+3)**(m+3)/(4*m**m);A=s.sqrt((m+3)/(2*m))/(2*s.pi)
  W=[(2*A,'lose the two-dimensional Stirling denominator factor'),(A/2,'double the Stirling denominator factor'),(s.sqrt((m+3)/m)/(2*s.pi),'omit the second block-size factor two'),(s.sqrt(2*m/(m+3))/(2*s.pi),'invert the variance normalization'),(s.sqrt((m+3)/(2*m))/s.sqrt(2*s.pi),'retain only one square-root Stirling denominator'),(s.sqrt((m+2)/(2*m))/(2*s.pi),'drop one block from the total-size square root')]
  Q=r'S_N=\sum_{k=-N}^{N}(-1)^k\binom{3N}{2N+k}\binom{'+L(m+2)+r'N}{'+L(m)+r'N+k}\binom{'+L(m+1)+r'N}{N+k}.\quad\lim_{N\to\infty}N\left('+L(1/B)+r'\right)^NS_N=?'
  steps=[T('Let CT mean the coefficient of zero powers in all three Laurent variables. Pair opposite variable ratios in the following product.'),r'D(a,b,c)=\operatorname{CT}\prod_{i\ne j}(1-x_i/x_j)^{a_i},\qquad(a_1,a_2,a_3)=(a,b,c).',r'(1-u)^a(1-u^{-1})^b=\sum_k(-1)^k\binom{a+b}{b+k}u^k.',T('The three cyclic exponents agree exactly when the product term is constant, giving the displayed alternating sum for exponent sizes N, twice N, and the third displayed multiple of N.'),T('For positive integer exponents, the rational identity below gives the three-term decrement recurrence. At a zero exponent, the corresponding variable constant term reduces to the two-variable binomial identity.'),r'\sum_{i=1}^{3}\prod_{j\ne i}(1-x_i/x_j)^{-1}=1,\qquad D(a,b,c)=D(a-1,b,c)+D(a,b-1,c)+D(a,b,c-1).',r'D(a,b,c)=\frac{(a+b+c)!}{a!b!c!},\qquad S_N=\frac{('+L(m+3)+r'N)!}{N!(2N)!('+L(m)+r'N)!}.',T('Apply Stirling to the four factorials. The exponential factor is canceled by the normalization in the question, leaving the square-root factor and one inverse power of N.'),r'S_N\sim\frac1{2\pi N}\sqrt{\frac{'+L(m+3)+r'}{'+L(2*m)+r'}}\left('+L(B)+r'\right)^N,\qquad\lim_{N\to\infty}N\left('+L(1/B)+r'\right)^NS_N='+L(A)+r'.']
  checks=[]
  for N in [1,2,3]:checks.append(eq('unequal-block Dyson finite check N='+str(N),sum(s.Integer(-1)**k*s.binomial(3*N,2*N+k)*s.binomial((m+2)*N,m*N+k)*s.binomial((m+1)*N,N+k) for k in range(-N,N+1)),s.factorial((m+3)*N)/(s.factorial(N)*s.factorial(2*N)*s.factorial(m*N))))
  return numeric(fid,i,Q,A,W,steps,checks,['The Good recurrence plus zero-exponent boundary values proves the factorial constant term by induction on total degree. The multinomial factorial expression obeys the same recurrence and boundaries. The two-dimensional Stirling prefactor is (2pi N)^-1 sqrt((m+3)/(2m)); no cancellation estimate based on numerical summation is used.'],{'thirdBlockRatio':int(m),'qualityRoute':'unequal-block-asymptotic-v2'})

 @register('Pade-cancellation-order','Pade-exponential-integral-error','exact-beta-remainder-and-Laplace-maximum','An exponential approximation is evaluated on a moving scale; an exact beta remainder and a global interior maximum determine its exponential growth.',('integration by parts','Laplace maximum principle','Stirling asymptotics'))
 def pade(fid,i):
  a=R(i+1,2);d=s.sqrt(a*a+4);t0=(a-2+d)/(2*a);A=(d-2)*s.exp((a+2+d)/2)
  W=[(a*a*s.exp(2+a/2)/4,'assume the symmetric midpoint remains maximal after exponential tilting'),((d-2)*s.exp((a-2+d)/2),'omit the exponential factor from two Stirling denominators'),((d-2)*s.exp((2-a+d)/2),'reverse the sign of the exponential tilt'),((d+2)*s.exp((a+2+d)/2),'choose the nonphysical quadratic root for the product factor'),((d-2)*s.exp((a+2+d)/2)/a**2,'omit the moving-argument squared scale'),((d-2)*s.exp((a+2+d)/2)*a**2,'include the moving-argument scale twice')]
  Q=r'Q_N(z)=\sum_{k=0}^{N}\frac{(-1)^k}{k!}\binom{2N-k}{N}z^k.\quad\lim_{N\to\infty}\left|Q_N\left('+L(a)+r'N\right)e^{'+L(a)+r'N}-Q_N\left(-'+L(a)+r'N\right)\right|^{1/N}=?'
  steps=[T('Repeated integration by parts with a beta polynomial gives an exact remainder, valid for every real z.'),r'Q_N(z)e^z-Q_N(-z)=\frac{(-1)^Nz^{2N+1}}{(N!)^2}\int_0^1t^N(1-t)^Ne^{tz}\,\mathrm{d}t.',T('At the moving positive argument, the nth root of the integral tends to the maximum of its continuous nonnegative base. This follows by bounding above by its maximum and below on any fixed small interval around a maximizer.'),r'f(t)=t(1-t)e^{'+L(a)+r't},\qquad\left(\int_0^1f(t)^N\,\mathrm{d}t\right)^{1/N}\longrightarrow\max_{0\le t\le1}f(t).',r'\frac{f\prime(t)}{f(t)}=\frac1t-\frac1{1-t}+'+L(a)+r',\qquad t_*='+L(t0)+r'.',T('The logarithmic derivative decreases strictly from positive infinity to negative infinity, so this is the unique global maximum. Stirling gives the remaining moving-argument normalization.'),r'\left(\frac{('+L(a)+r'N)^{2N+1}}{(N!)^2}\right)^{1/N}\longrightarrow '+L(a*a)+r'e^2.',r'\lim_{N\to\infty}|Q_N('+L(a)+r'N)e^{'+L(a)+r'N}-Q_N(-'+L(a)+r'N)|^{1/N}='+L(a*a)+r'e^2t_*(1-t_*)e^{'+L(a)+r't_*}='+L(A)+r'.']
  checks=[eq('critical point equation',s.simplify(1/t0-1/(1-t0)+a),0),truth('unique critical point lies inside interval',0<t0<1),eq('saddle product factor',s.simplify(a*a*t0*(1-t0)),d-2),eq('saddle exponent',2+a*t0,(a+2+d)/2)]
  return numeric(fid,i,Q,A,W,steps,checks,['The exact remainder follows by moving 2N+1 derivatives from the exponential onto t^N(1-t)^N; endpoint derivatives below N vanish and the final derivative is zero. The bounded-interval maximum principle needs only continuity and nonnegativity, and the unique maximum is positive. All roots in the explicit critical point are positive principal roots.'],{'movingScale':str(a),'qualityRoute':'moving-scale-Laplace-v2'})

 @register('Poisson-partition-moment','Poisson-growing-moment-saddle','exponential-moment-bound-and-single-term-sharpness','A moving Poisson mean and growing moment require optimizing an exponential majorant and matching it with a Stirling lower bound; a fixed Bell table cannot answer the limit.',('exponential series','Stirling asymptotics','optimization'))
 def poisson(fid,i):
  a=[R(1,2),R(2,3),R(3,4),R(1),R(4,3),R(3,2),R(2),R(3)][i];lam=s.exp(-a)/a;A=s.exp(1/a-1-lam)/a
  W=[(s.exp(1/a-1)/a,'omit the Poisson normalization factor'),(s.exp(1/a-lam)/a,'omit the factorial Stirling exponential'),(s.exp(-1-lam)/a,'omit the optimized exponential-moment contribution'),(a*s.exp(1/a-1-lam),'invert the dominant scaled index'),(s.exp(1/a-1-lam)/a**2,'divide twice by the optimization parameter'),(s.exp(1/a-2-lam)/a,'introduce the factorial exponential twice')]
  Q=r'\lambda='+L(lam)+r',\qquad S_N=e^{-\lambda N}\sum_{k=0}^{\infty}\frac{k^N(\lambda N)^k}{k!}\quad(N=1,2,\ldots).\quad\lim_{N\to\infty}\frac{S_N^{1/N}}{N}=?'
  steps=[T('For any positive parameter t, maximize a power times a decaying exponential to bound every nonnegative summand index.'),r'u^N\le\left(\frac{N}{et}\right)^Ne^{tu}\quad(u\ge0),\qquad S_N\le\left(\frac{N}{et}\right)^N\exp\!\left(\lambda N(e^t-1)\right).',T('The logarithm of the resulting root bound is minimized when the parameter times its exponential equals the reciprocal of lambda.'),r'-\frac1t+\lambda e^t=0,\qquad t='+L(a)+r',\qquad\limsup_{N\to\infty}\frac{S_N^{1/N}}N\le\frac1{'+L(a)+r'}\exp\!\left('+L(1/a-1-lam)+r'\right).',T('For the matching lower bound keep just the term at the integer part of N divided by this optimizing parameter. Its scaled index tends to the displayed positive limit.'),r'k_N=\left\lfloor\frac N{'+L(a)+r'}\right\rfloor,\qquad\frac{k_N}N\longrightarrow c=\frac1{'+L(a)+r'},\qquad S_N\ge e^{-\lambda N}\frac{k_N^N(\lambda N)^{k_N}}{k_N!}.',T('Take logarithms, divide by N, subtract the logarithm of N, and apply Stirling to the one factorial. The rounding error is lower order.'),r'\liminf_{N\to\infty}\ln\!\left(\frac{S_N^{1/N}}N\right)\ge\ln c+c\ln(\lambda/c)+c-\lambda=\ln c-1+c-\lambda.',T('The bounds agree because the chosen c satisfies c times the logarithm of c divided by lambda equals one.'),r'\lim_{N\to\infty}\frac{S_N^{1/N}}N='+L(A)+r'.']
  checks=[eq('optimization parameter equation',a*lam*s.exp(a),1),eq('dominant-index entropy identity',s.expand_log((1/a)*s.log((1/a)/lam),force=True),1),truth('positive moment mean',lam>0)]
  return numeric(fid,i,Q,A,W,steps,checks,['For fixed N the factorial series is absolutely convergent by the ratio test. The exponential majorant is derived by differentiating u^N exp(-tu), not by assuming a moment asymptotic. The explicit t solves the unique critical point of -ln t+lambda(e^t-1), whose second derivative is positive. Stirling at k_N~cN gives a matching single-term lower bound.'],{'saddleParameter':str(a),'qualityRoute':'growing-Poisson-moment-v2'})

 @register('Hilbert-kernel-sharp-constant','sharp-Hilbert-series-inequality','asymmetric-Schur-test-and-logarithmic-extremizers','An asymmetric operator kernel requires matching row and column weights and an extremizing sequence; the parameter changes the operator aspect ratio, not an external scalar.',('Cauchy-Schwarz','integral comparison','sharp constants'))
 def hilbert(fid,i):
  m=s.Integer(i+2);A=s.pi/s.sqrt(m)
  W=[(s.pi/m,'use the full axis scaling instead of its square root'),(s.pi,'ignore the different column scale'),(s.pi*s.sqrt(m),'invert the column Jacobian'),(2*s.pi/s.sqrt(m),'count both symmetric halves of the integral'),(s.pi/(2*s.sqrt(m)),'discard one half of the beta integral'),(s.pi/(m*s.sqrt(m)),'apply the column scaling once more')]
  Q=T('Find the least constant C for which the inequality holds for all positive integers N and all real sequences of the indicated finite length.')+r'\quad\left|\sum_{j,k=1}^{N}\frac{a_jb_k}{j+'+L(m)+r'k}\right|\le C\left(\sum_{j=1}^{N}a_j^2\right)^{1/2}\left(\sum_{k=1}^{N}b_k^2\right)^{1/2}.'
  steps=[T('Use reciprocal-square-root weights in both indices. Decreasing integral comparison bounds both the row and column sums by the same constant.'),r'u_j=j^{-1/2},\quad v_k=k^{-1/2},\qquad\sum_{k\ge1}\frac{v_k}{j+'+L(m)+r'k}\le\int_0^\infty\frac{t^{-1/2}}{j+'+L(m)+r't}\,\mathrm{d}t=\frac\pi{\sqrt{'+L(m)+r'}}u_j,',r'\sum_{j\ge1}\frac{u_j}{j+'+L(m)+r'k}\le\int_0^\infty\frac{t^{-1/2}}{t+'+L(m)+r'k}\,\mathrm{d}t=\frac\pi{\sqrt{'+L(m)+r'}}v_k.',T('Apply Cauchy-Schwarz to the bilinear sum after inserting the reciprocal weight ratios into its two factors. The two displayed bounds then give the required upper constant.'),r'K_{jk}=\frac1{j+'+L(m)+r'k},\quad\sum_{j,k}K_{jk}|a_jb_k|\le\left(\sum_{j,k}K_{jk}a_j^2\frac{v_k}{u_j}\right)^{1/2}\left(\sum_{j,k}K_{jk}b_k^2\frac{u_j}{v_k}\right)^{1/2}.',T('For sharpness take both sequences to be the reciprocal-square-root sequence through N. For indices j between a large fixed cutoff and N divided by that cutoff, the normalized inner sum approaches the full beta integral uniformly as the cutoff increases.'),r'\sqrt j\sum_{k=1}^{N}\frac{k^{-1/2}}{j+'+L(m)+r'k}\ge\int_{1/K}^{K}\frac{u^{-1/2}}{1+'+L(m)+r'u}\,\mathrm{d}u\quad(K\le j\le N/K).',T('Sum over these middle indices with weight one over j. Dividing by the harmonic sum through N and first sending N, then K, to infinity gives the matching lower constant.'),r'C=\int_0^\infty\frac{u^{-1/2}}{1+'+L(m)+r'u}\,\mathrm{d}u=\frac\pi{\sqrt{'+L(m)+r'}}.']
  u=s.symbols('u',positive=True);F=2/s.sqrt(m)*s.atan(s.sqrt(m*u));checks=[eq('beta comparison primitive',s.diff(F,u),1/(s.sqrt(u)*(1+m*u))),eq('full comparison integral',s.limit(F,u,s.oo)-s.limit(F,u,0),A)]
  return numeric(fid,i,Q,A,W,steps,checks,['All sums in the upper bound are finite, and the positive comparison integrals bound their extensions. For the sharp lower bound, a decreasing k-integrand has its sum at least its integral from 1 to N+1. After t=j u this contains [1/K,K] whenever K<=j<=N/K. The fraction of H_N in that middle logarithmic range tends to one for fixed K. The beta integral tends to pi/sqrt(m) as K increases. No symmetry of the asymmetric matrix is assumed.'],{'columnScale':int(m),'qualityRoute':'asymmetric-Hilbert-v2'})

 @register('conditional-double-sum-orders','conditional-double-series-order','mixed-discrete-difference-and-rectangular-limits','A hidden two-variable telescope has distinct iterated and square cutoffs; absolute divergence must be established to explain the order dependence.',('double sums','telescoping','absolute convergence'))
 def double_orders(fid,i):
  a=s.Integer(i+2);b=a*a+1;f=a/(a+b);A=s.Tuple(f-1,f,f-R(1,2));code=s.srepr(A)
  values=[(A,'correct'),(s.Tuple(f,f-1,f-R(1,2)),'reverse the meanings of the two iterated orders'),(s.Tuple(f-R(1,2),f-R(1,2),f-R(1,2)),'assume symmetric cutoffs equal both iterated sums'),(s.Tuple(f-1,f,0),'assume a square cutoff cancels despite the unequal lower bounds')]
  opts=[(s.srepr(v),L(v),why) for v,why in values]
  Q=r'c_{mn}=\frac{m-n}{(m+n)(m+n+1)(m+n+2)}.\quad A=\sum_{m='+L(a)+r'}^{\infty}\left(\sum_{n='+L(b)+r'}^{\infty}c_{mn}\right),\quad B=\sum_{n='+L(b)+r'}^{\infty}\left(\sum_{m='+L(a)+r'}^{\infty}c_{mn}\right),\quad D=\lim_{N\to\infty}\sum_{m='+L(a)+r'}^{N}\sum_{n='+L(b)+r'}^{N}c_{mn}.\quad(A,B,D)=?'
  steps=[T('Introduce a rational potential whose mixed forward difference is the given summand.'),r'F(m,n)=\frac m{m+n},\qquad c_{mn}=F(m+1,n+1)-F(m+1,n)-F(m,n+1)+F(m,n).',r'\sum_{m='+L(a)+r'}^{M}\sum_{n='+L(b)+r'}^{N}c_{mn}=F(M+1,N+1)-F(M+1,'+L(b)+r')-F('+L(a)+r',N+1)+F('+L(a)+','+L(b)+r').',T('For the first iterated order, let the inner n cutoff increase first; for the second order let the m cutoff increase first. On a square cutoff the first potential term is one half.'),r'A=F('+L(a)+','+L(b)+r')-1='+L(f-1)+r',\quad B=F('+L(a)+','+L(b)+r')='+L(f)+r',\quad D=F('+L(a)+','+L(b)+r')-\frac12='+L(f-R(1,2))+r'.',T('Each individual row and column is absolutely summable, but the full absolute double sum diverges. On the wedge where n lies between one quarter and one half of m, the positive summand is bounded below by a constant times one over m squared; there are a number of such terms proportional to m. The resulting harmonic lower bound explains why changing order is not justified.'),L(A)]
  u,v=s.symbols('u v',positive=True);F=lambda u,v:u/(u+v);checks=[eq('mixed finite difference identity',F(u+1,v+1)-F(u+1,v)-F(u,v+1)+F(u,v),(u-v)/((u+v)*(u+v+1)*(u+v+2))),eq('square diagonal potential',F(u,u),R(1,2))]
  return categorical(fid,i,Q,code,opts,steps,checks,['For each fixed row or column the summand is O(index^-2), so the inner sums exist absolutely. The finite rectangular telescope determines all three requested limits with the indicated order. For large m and m/4<=n<=m/2, numerator>=m/2 and denominator<=((3/2)m+2)^3, giving a uniform positive multiple of m^-2. The allowed n count is at least m/5 for large m, so the absolute double series dominates a harmonic tail.'],{'lowerM':int(a),'lowerN':int(b),'qualityRoute':'double-order-v1'})

 @register('Hardy-mean-sharp-constant','sharp-discrete-Hardy-power-mean','weighted-Holder-tail-telescope-and-sharpness','The power-mean operator norm requires an auxiliary sequence tailored to Holder and a matching finite-support asymptotic; its exponent changes the operator space.',('Holder inequality','Bernoulli inequality','integral comparison'))
 def hardy(fid,i):
  p=[R(3,2),R(2),R(5,2),R(3),R(4),R(5),R(6),R(8)][i];c=p/(p-1);A=c**p
  W=[(c,'forget the final Holder power'),(c**(p-1),'omit one tail-normalization factor'),(c**(p+1),'count the tail normalization twice'),(c**(2*p),'raise the operator bound twice'),(p**p,'omit the conjugate-exponent denominator'),((p/(p+1))**p,'use the wrong sign in the conjugate exponent')]
  Q=T('Find the least real C for which the inequality holds for every nonnegative sequence whose displayed power sum is finite.')+r'\quad p='+L(p)+r',\qquad\sum_{n=1}^{\infty}\left(\frac{a_1+\cdots+a_n}{n}\right)^p\le C\sum_{n=1}^{\infty}a_n^p.'
